/**
 * Switch Realm (Human C&E vs Fauna/Dinosaurs/Aves C&E)
 */
function switchRealm(newRealm) {
  state.activeRealm = newRealm;
  state.currentCategory = "All";
  state.currentPage = 1;
  updateRealmView();
}

